from pathlib import Path
import sys
import threading


class AppConfig:
    CONFIG_FILE = "config.ini"
    DEFAULT_CONFIG = {
        "Watcher": {
            "feed_url": "https://www.theguardian.com/uk/rss",
            "check_interval": 31,
            "min_reward": 0.0,
            "enable_notifications": True,
