            "user_id": 0,
            "user_session": "REPLACE_WITH_YOUR_SESSION_TOKEN",
        },
        "Paths": {
            "sound_file": "C:\\Windows\\Media\\chimes.wav",
            "log_file": "logs/gengowatcher.log",
            "notification_icon_path": "",
